<?php $title='Detalhes do módulo'; ?>
<section class="page-head"><div><h1><?=e($project['name'])?></h1><p><?=e($project['description'])?></p></div><div><?php if(!empty($project['admin_url'])):?><form method="post" action="<?=e(base_url('projetos/'.$project['id'].'/administrar'))?>" target="_blank" rel="noopener noreferrer"><?=csrf_field()?><button class="btn primary" type="submit">Administrar</button></form><?php endif;?></div></section>
<div class="detail-grid"><section class="panel"><h2>Cadastro do projeto</h2><dl><dt>Nome</dt><dd><?=e($project['name'])?></dd><dt>Código</dt><dd><code><?=e($project['code'])?></code></dd><dt>URL</dt><dd><?=e($project['url']?:'Não configurada')?></dd><dt>URL administrativa</dt><dd><?=e($project['admin_url']?:'Não configurada')?></dd><dt>Versão</dt><dd><?=e($project['version'])?></dd><dt>Categoria</dt><dd><?=e($project['category']?:'Não informada')?></dd><?php if($project['status']!=='deploying'):?><dt>Status</dt><dd><?=e(project_status_label($project['status']))?></dd><?php endif;?></dl></section></div>
<section class="panel"><h2>Clientes com acesso</h2><?php if(!$clients):?><div class="empty">Nenhum cliente vinculado.</div><?php else:?><div class="project-list"><?php foreach($clients as$c):?><a href="<?=e(base_url('clientes/'.$c['id']))?>"><b><?=e($c['name'])?></b><small><?=e($c['identifier'])?></small></a><?php endforeach;?></div><?php endif;?></section>
<section class="panel"><h2>Atividade recente</h2><?php if(!$activities):?><div class="empty">Nenhuma atividade recente.</div><?php else:?><div class="timeline"><?php foreach($activities as$activity):?><div><span class="dot"></span><p><b><?=e($activity['user_name']??'Sistema')?></b> — <?=e($activity['description'])?><small><?=e(date('d/m/Y H:i',strtotime($activity['created_at'])))?></small></p></div><?php endforeach;?></div><?php endif;?></section>
